package patterns.structural;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class Proxy {
public interface WeatherService{java.util.concurrent.CompletableFuture<Double> temperature(String city);}public static class CachingWeatherProxy implements WeatherService{private record Cached(double value,long expiresAt){}private final Map<String,Cached> cache=new HashMap<>();private final WeatherService service;private final long ttlMs;private final LongSupplier now;public CachingWeatherProxy(WeatherService s){this(s,60000,System::currentTimeMillis);}public CachingWeatherProxy(WeatherService s,long ttl,LongSupplier now){service=s;ttlMs=ttl;this.now=now;}public java.util.concurrent.CompletableFuture<Double> temperature(String city){Cached c=cache.get(city);if(c!=null&&c.expiresAt>now.getAsLong())return java.util.concurrent.CompletableFuture.completedFuture(c.value);try{return service.temperature(city).thenApply(v->{cache.put(city,new Cached(v,now.getAsLong()+ttlMs));return v;});}catch(Throwable e){return java.util.concurrent.CompletableFuture.failedFuture(e);}}}public static class AccessControlProxy implements WeatherService{private final WeatherService service;private final BooleanSupplier allowed;public AccessControlProxy(WeatherService s,BooleanSupplier allowed){service=s;this.allowed=allowed;}public java.util.concurrent.CompletableFuture<Double> temperature(String city){return allowed.getAsBoolean()?service.temperature(city):java.util.concurrent.CompletableFuture.failedFuture(new IllegalAccessException("Access denied"));}}public static <K,V> Map<K,V> createValidatedObject(Map<K,V> target,BiPredicate<K,V> validate){return new AbstractMap<>(){public V put(K k,V v){if(!validate.test(k,v))throw new IllegalArgumentException("Invalid value for "+k);return target.put(k,v);}public Set<Map.Entry<K,V>> entrySet(){return new AbstractSet<>(){public int size(){return target.size();}public Iterator<Map.Entry<K,V>> iterator(){Iterator<Map.Entry<K,V>> i=target.entrySet().iterator();return new Iterator<>(){public boolean hasNext(){return i.hasNext();}public Map.Entry<K,V> next(){Map.Entry<K,V> e=i.next();return new AbstractMap.SimpleEntry<>(e){public V setValue(V v){if(!validate.test(getKey(),v))throw new IllegalArgumentException();V old=e.setValue(v);super.setValue(v);return old;}};}public void remove(){i.remove();}};}};}};}
}
